/**
 * Concrete bindings for this Worker.
 *
 * `Env` is generated by `npx wrangler types` from wrangler.jsonc, so the binding
 * set is still driven by the config. Wrangler emits literal types for `vars` (the
 * union across environments) and marks them optional, so those fields are widened
 * here for runtime reads. `JWT_SIGNING_KEY` is a secret set with
 * `wrangler secret put`, which is why it never appears in the generated config.
 */
export type AppEnv = Omit<
  Env,
  'DB' | 'APP_NAME' | 'APP_ENV' | 'ALLOWED_ORIGINS' | 'ACCESS_TOKEN_TTL_SECONDS'
> & {
  readonly DB: D1Database;
  readonly APP_NAME: string;
  readonly APP_ENV: string;
  readonly ALLOWED_ORIGINS: string;
  readonly ACCESS_TOKEN_TTL_SECONDS: string;
  readonly JWT_SIGNING_KEY: string;
  readonly ID_ENCRYPTION_KEY?: string;
  readonly ADMIN_EMAIL?: string;
  readonly ADMIN_PASSWORD?: string;
};
